// İMAM NƏVƏVİNİN QIRX HƏDİSİ (əl-Ərbəun ən-Nəvəviyyə) — 42 hədis
// Ərəb mətni: fawazahmed0/hadith-api «ara-nawawi» (yalnız mənbə/qiymət
// hissəsi ayrılıb, kodlaşma xətaları düzəldilib). Mənbə nömrələri Buxari,
// Müslim, Tirmizi, Əbu Davud, Nəsai, İbn Macə nəşrləri ilə yoxlanılıb.
