export const NAWAWI_INTRO = {
  az: "İmam Yəhya ibn Şərəf ən-Nəvəvi (631–676 h.) bu kiçik toplunu dinin əsas qaydalarını özündə cəmləyən qırx iki hədisdən tərtib etmişdir; alimlər onların hər birini İslamın böyük əsaslarından biri sayırlar. Hədislərin çoxu Buxari və Müslimin «Səhih»lərindəndir, qalanlarının dərəcəsi isə hər hədisin altında göstərilir. Faydalar İbn Dəqiq əl-İd, İbn Rəcəb («Cəmiul-ülum vəl-hikəm») və İbn Useyminin şərhlərinə əsaslanır.",
  en: "Imam Yahya ibn Sharaf an-Nawawi (631–676 AH) compiled this short collection of forty-two hadith, each of which the scholars regard as one of the great foundations of the religion. Most of them are from the Sahihs of al-Bukhari and Muslim; the grading of the rest is noted under each hadith. The benefits are drawn from the explanations of Ibn Daqiq al-Id, Ibn Rajab (Jami’ al-Ulum wal-Hikam) and Ibn Uthaymin.",
  ru: "Имам Яхья ибн Шараф ан-Навави (631–676 г. х.) составил этот небольшой сборник из сорока двух хадисов, каждый из которых учёные считают одной из великих основ религии. Большинство из них — из «Сахихов» аль-Бухари и Муслима, а степень достоверности остальных указана под каждым хадисом. Польза извлечена из разъяснений Ибн Дакик аль-Ида, Ибн Раджаба («Джами‘ аль-‘улюм ва-ль-хикам») и Ибн ‘Усаймина.",
  ar: "جمع الإمام يحيى بن شرف النووي (631–676هـ) هذا المتن المختصر من اثنين وأربعين حديثًا، كلُّ حديث منها قاعدة عظيمة من قواعد الدين. وأكثرها في صحيحي البخاري ومسلم، وبُيِّنت درجة غيرها تحت كل حديث. والفوائد مستخرجة من شروح ابن دقيق العيد وابن رجب (جامع العلوم والحكم) وابن عثيمين.",
  tr: "İmam Yahya b. Şeref en-Nevevi (631–676 h.) bu kısa eseri, her biri âlimlerce dinin büyük temellerinden sayılan kırk iki hadisten derlemiştir. Hadislerin çoğu Buhari ve Müslim’in «Sahih»lerindendir; diğerlerinin derecesi her hadisin altında belirtilmiştir. Faydalar İbn Dakikü’l-İd, İbn Receb («Camiu’l-Ulum ve’l-Hikem») ve İbn Useymin’in şerhlerinden alınmıştır.",
}

