      ru: "Передаётся, что мать верующих Умм ‘Абдуллах ‘Аиша (да будет доволен ею Аллах) сказала: «Посланник Аллаха (ﷺ) сказал: “Кто внесёт в это наше дело (религию) то, что к нему не относится, — это будет отвергнуто”». А в версии Муслима: «Кто совершит дело, на которое нет нашего повеления, — оно будет отвергнуто».",
