      ru: "Передаётся, что Абу Хурайра ‘Абд ар-Рахман ибн Сахр (да будет доволен им Аллах) сказал: «Я слышал, как Посланник Аллаха (ﷺ) говорил: “То, что я вам запретил, избегайте, а то, что я вам велел, исполняйте, насколько сможете. Поистине, тех, кто был до вас, погубили лишь их многочисленные вопросы и разногласия с их пророками”».",
