    ar: "عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنْت خَلْفَ رَسُولِ اللَّهِ صلى الله عليه وسلم يَوْمًا، فَقَالَ: يَا غُلَامِ! إنِّي أُعَلِّمُك كَلِمَاتٍ: احْفَظْ اللَّهَ يَحْفَظْك، احْفَظْ اللَّهَ تَجِدْهُ تُجَاهَك، إذَا سَأَلْت فَاسْأَلْ اللَّهَ، وَإِذَا اسْتَعَنْت فَاسْتَعِنْ بِاَللَّهِ، وَاعْلَمْ أَنَّ الْأُمَّةَ لَوْ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوك بِشَيْءٍ لَمْ يَنْفَعُوك إلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَك، وَإِنْ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوك بِشَيْءٍ لَمْ يَضُرُّوك إلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْك؛ رُفِعَتْ الْأَقْلَامُ، وَجَفَّتْ الصُّحُفُ. وَفِي رِوَايَةِ غَيْرِ التِّرْمِذِيِّ: «احْفَظْ اللَّهَ تَجِدْهُ أَمَامَك، تَعَرَّفْ إلَى اللَّهِ فِي الرَّخَاءِ يَعْرِفُك فِي الشِّدَّةِ، وَاعْلَمْ أَنَّ مَا أَخْطَأَك لَمْ يَكُنْ لِيُصِيبَك، وَمَا أَصَابَك لَمْ يَكُنْ لِيُخْطِئَك، وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ، وَأَنْ الْفَرَجَ مَعَ الْكَرْبِ، وَأَنَّ مَعَ الْعُسْرِ يُسْرًا»",
    text: {
      az: "Abdullah ibn Abbas (Allah onlardan razı olsun) dedi: «Bir gün Allahın Rəsulunun (ﷺ) arxasında idim. O buyurdu: “Ey oğlan, sənə bir neçə kəlmə öyrədirəm: Allahı (Onun hədlərini) qoru ki, O da səni qorusun. Allahı qoru ki, Onu qarşında tapasan. İstədikdə Allahdan istə, kömək dilədikdə Allahdan kömək dilə. Bil ki, bütün ümmət sənə bir fayda vermək üçün toplaşsa, sənə Allahın sənin üçün yazdığından başqa heç bir fayda verə bilməz. Sənə bir zərər vermək üçün toplaşsalar, sənə Allahın sənin əleyhinə yazdığından başqa heç bir zərər verə bilməzlər. Qələmlər qaldırılmış, səhifələr qurumuşdur”». Tirmizidən başqasının rəvayətində isə: «Allahı qoru ki, Onu önündə tapasan. Rahatlıqda Allahı tanı ki, O da səni çətinlikdə tanısın. Bil ki, sənə dəyməyən şey sənə dəyəsi deyildi, sənə dəyən şey isə səndən yan keçəsi deyildi. Bil ki, zəfər səbrlə, qurtuluş sıxıntı ilə, çətinliklə birlikdə isə asanlıq vardır».",
      en: "From Abdullah ibn Abbas (may Allah be pleased with them both), who said: One day I was behind the Messenger of Allah (ﷺ), and he said: “O boy, I will teach you some words: Be mindful of Allah and He will protect you. Be mindful of Allah and you will find Him before you. When you ask, ask Allah; and when you seek help, seek help from Allah. Know that if the whole nation gathered to benefit you with something, they would not benefit you except with what Allah has already written for you; and if they gathered to harm you with something, they would not harm you except with what Allah has already written against you. The pens have been lifted and the pages have dried.” In a narration other than at-Tirmidhi’s: “Be mindful of Allah and you will find Him in front of you. Get to know Allah in prosperity and He will know you in hardship. Know that what missed you was never going to befall you, and what befell you was never going to miss you. Know that victory comes with patience, relief comes with distress, and with hardship comes ease.”",
      ru: "Передаётся, что ‘Абдуллах ибн ‘Аббас (да будет доволен Аллах ими обоими) сказал: «Однажды я сидел позади Посланника Аллаха (ﷺ), и он сказал: “О юноша, я научу тебя словам: храни Аллаха — и Он сохранит тебя; храни Аллаха — и найдёшь Его перед собой. Если просишь — проси Аллаха, а если ищешь помощи — ищи её у Аллаха. Знай, что если вся община соберётся, чтобы принести тебе пользу, она принесёт тебе пользу лишь в том, что Аллах уже предписал тебе; а если соберутся, чтобы навредить тебе, то навредят тебе лишь тем, что Аллах уже предписал против тебя. Перья подняты, а свитки высохли”». В версии, переданной не ат-Тирмизи: «Храни Аллаха — и найдёшь Его впереди себя. Знай Аллаха в благополучии — и Он узнает тебя в беде. Знай, что то, что миновало тебя, не должно было тебя постичь, а то, что постигло тебя, не должно было тебя миновать. Знай, что победа — с терпением, облегчение — со скорбью, а с тягостью — лёгкость».",
      tr: "Abdullah b. Abbas (Allah ikisinden de razı olsun) şöyle dedi: «Bir gün Allah Resulü’nün (ﷺ) arkasındaydım. Bana şöyle buyurdu: “Ey çocuk, sana birkaç söz öğreteyim: Allah’ı (O’nun sınırlarını) gözet ki O da seni korusun. Allah’ı gözet ki O’nu karşında bulasın. İstediğinde Allah’tan iste, yardım dilediğinde Allah’tan yardım dile. Bil ki bütün ümmet sana bir fayda vermek için toplansa, Allah’ın senin için yazdığından başka bir fayda veremezler. Sana bir zarar vermek için toplansalar, Allah’ın senin aleyhine yazdığından başka bir zarar veremezler. Kalemler kaldırılmış, sayfalar kurumuştur”». Tirmizi dışındakilerin rivayetinde ise: «Allah’ı gözet ki O’nu önünde bulasın. Bollukta Allah’ı tanı ki O da seni darlıkta tanısın. Bil ki sana isabet etmeyen şey zaten sana isabet edecek değildi; sana isabet eden şey de seni ıskalayacak değildi. Bil ki zafer sabırla, kurtuluş sıkıntıyla, zorlukla birlikte de kolaylık vardır».",
    },
