    ar: "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم كُلُّ سُلَامَى مِنْ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ تَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الْأَذَى عَنْ الطَّرِيقِ صَدَقَةٌ.",
    text: {
      az: "Əbu Hureyrə (Allah ondan razı olsun) dedi: «Allahın Rəsulu (ﷺ) buyurdu: “Günəşin doğduğu hər gün insanın hər oynağına bir sədəqə düşür: iki nəfərin arasında ədalətlə barışıq yaratmağın sədəqədir, bir kişiyə minik heyvanına minməkdə kömək edib onu mindirməyin və ya yükünü onun üstünə qaldırmağın sədəqədir, xoş söz sədəqədir, namaza getdiyin hər addım sədəqədir və yoldan əziyyət verən şeyi kənarlaşdırmağın sədəqədir”».",
      en: "From Abu Hurayrah (may Allah be pleased with him), who said: The Messenger of Allah (ﷺ) said: “Every joint of a person owes a charity every day the sun rises: judging justly between two people is charity; helping a man with his mount, lifting him onto it or lifting his belongings onto it, is charity; a good word is charity; every step you take towards the prayer is charity; and removing something harmful from the road is charity.”",
      ru: "Передаётся, что Абу Хурайра (да будет доволен им Аллах) сказал: «Посланник Аллаха (ﷺ) сказал: “За каждый сустав человека полагается милостыня каждый день, когда восходит солнце: рассудить по справедливости двоих — милостыня; помочь человеку с его верховым животным, посадив его на него или подняв на него его поклажу, — милостыня; доброе слово — милостыня; каждый шаг, который ты делаешь к молитве, — милостыня; и убрать с дороги то, что причиняет вред, — милостыня”».",
      tr: "Ebu Hureyre (Allah ondan razı olsun) şöyle dedi: «Allah Resulü (ﷺ) buyurdu: “Güneşin doğduğu her gün insanın her eklemi için bir sadaka gerekir: iki kişinin arasını adaletle bulman sadakadır; bir adama binitine binmesinde yardım edip onu bindirmen veya yükünü bindirmen sadakadır; güzel söz sadakadır; namaza gitmek için attığın her adım sadakadır; yoldan eziyet veren şeyi kaldırman sadakadır”».",
    },
