        "İxtilaf zamanı qurtuluş Peyğəmbərin (ﷺ) Sünnəsinə və raşid xəlifələrin yoluna sarılmaqdadır.",
        "Dində hər bidət azğınlıqdır; ibadətdə «gözəl bidət» yoxdur.",
