        "Əl ilə dəyişdirmək səlahiyyəti olanlara (hakim, ailə başçısı) aiddir və daha böyük fitnəyə səbəb olmamalıdır.",
        "Münkəri dəyişdirərkən elm, yumşaqlıq və hikmət şərtdir.",
