        "Изменение рукой — для обладающих властью (правители, главы семей) и не должно вести к большему злу.",
        "Знание, мягкость и мудрость — условия изменения порицаемого.",
        "Бунт и вооружённое выступление против правителей из-за их ошибок не выводятся из этого хадиса; саляфы наставляли правителей наедине.",
