    ar: "عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، قَالَ: إنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ، ثُمَّ بَيَّنَ ذَلِكَ، فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إلَى سَبْعِمِائَةِ ضِعْفٍ إلَى أَضْعَافٍ كَثِيرَةٍ، وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ سَيِّئَةً وَاحِدَةً.",
    text: {
      az: "İbn Abbas (Allah onlardan razı olsun) Allahın Rəsulundan (ﷺ), onun da mübarək və uca Rəbbindən rəvayət etdiyinə görə buyurdu: «Şübhəsiz, Allah yaxşılıqları və pislikləri yazdı, sonra bunu açıqladı. Kim bir yaxşılığa niyyət edib onu etməsə, Allah onu Öz yanında tam bir yaxşılıq kimi yazar. Əgər ona niyyət edib onu edərsə, Allah onu Öz yanında on yaxşılıqdan yeddi yüz qata, hətta daha çox qata qədər yazar. Kim bir pisliyə niyyət edib onu etməsə, Allah onu Öz yanında tam bir yaxşılıq kimi yazar. Əgər ona niyyət edib onu edərsə, Allah onu tək bir pislik kimi yazar».",
      en: "From Ibn Abbas (may Allah be pleased with them both), from the Messenger of Allah (ﷺ), in what he narrates from his Lord, Blessed and Exalted, who said: “Allah has written down good deeds and bad deeds, then He made that clear. Whoever intends a good deed but does not do it, Allah writes it with Himself as one complete good deed. If he intends it and does it, Allah writes it with Himself as ten good deeds up to seven hundred times, up to many times more. Whoever intends a bad deed but does not do it, Allah writes it with Himself as one complete good deed. And if he intends it and does it, Allah writes it as one single bad deed.”",
      ru: "Передаётся от Ибн ‘Аббаса (да будет доволен Аллах ими обоими) от Посланника Аллаха (ﷺ) из того, что он передаёт от своего Господа, Благословенного и Всевышнего: «Поистине, Аллах записал добрые и дурные дела, а затем разъяснил это. Кто вознамерится совершить доброе дело, но не совершит его, тому Аллах запишет у Себя одно полное доброе дело. Если же он вознамерится и совершит его, Аллах запишет ему у Себя от десяти добрых дел до семисот крат и до многих крат больше. Кто вознамерится совершить дурное дело, но не совершит его, тому Аллах запишет у Себя одно полное доброе дело. А если вознамерится и совершит его, Аллах запишет ему лишь одно дурное дело».",
      tr: "İbn Abbas’ın (Allah ikisinden de razı olsun) Allah Resulü’nden (ﷺ), onun da mübarek ve yüce Rabbinden rivayet ettiğine göre şöyle buyurdu: «Şüphesiz Allah iyilikleri ve kötülükleri yazdı, sonra bunu açıkladı. Kim bir iyiliğe niyet edip onu yapmazsa, Allah onu katında tam bir iyilik olarak yazar. Eğer niyet edip onu yaparsa, Allah onu katında on iyilikten yedi yüz katına, hatta çok daha fazla katına kadar yazar. Kim bir kötülüğe niyet edip onu yapmazsa, Allah onu katında tam bir iyilik olarak yazar. Eğer niyet edip onu yaparsa, Allah onu yalnızca tek bir kötülük olarak yazar».",
    },
