        "Allaha ən sevimli yaxınlaşma fərzlərdir, sonra nafilələr gəlir; bu, Allahın məhəbbətinə səbəb olur.",
        "Sələfin izahına görə «onun qulağı olaram…» sözünün mənası budur: Allah bəndənin eşitməsini, görməsini və əməllərini Onun razı olduğu işlərə yönəldir və onu qoruyur. Bu, Allahın bəndə ilə birləşməsi (hulul, ittihad) deyil — bu fikir batildir.",
        "Allahın sevdiyi bəndənin duası qəbul olunur və o, Allahın himayəsindədir.",
