        "The most beloved way of drawing near to Allah is the obligations, then voluntary deeds, which bring about Allah’s love.",
        "According to the Salaf, “I become his hearing…” means Allah guides and aids the servant’s hearing, sight and actions so he uses them only in what pleases Him, and protects him. It does not mean that Allah unites with or indwells the servant (hulul, ittihad) — that belief is false.",
        "The supplication of the one Allah loves is answered, and he is under Allah’s protection.",
