        "Приближённый (вали) Аллаха — каждый верующий, обладающий верой и богобоязненностью; это не связано с особой группой или притязаниями.",
        "Самое любимое Аллахом средство приближения — обязательное, затем добровольное, что приводит к любви Аллаха.",
        "Согласно саляфам, слова «Я становлюсь его слухом…» означают, что Аллах направляет и поддерживает слух, зрение и действия раба, чтобы он использовал их лишь в угодном Ему, и оберегает его. Это не означает соединения Аллаха с рабом или вселения в него (хулюль, иттихад) — такое убеждение ложно.",
